import {playerMail,clubTeamMail,mailUrl} from './mail-trigger-hooks.js';
// Dartflow club spaces. These are local demo records, not real memberships.
export function createClubs(ctx){
  const c=ctx,e=c.esc,I=c.icon,B=c.button;let filter='discover',tab='overview';
  const state=()=>c.db.play.clubs;
  const me=1;
  const isMember=club=>club.members.some(m=>m.id===me);
  const manage=club=>c.db.role==='admin'||club.members.some(m=>m.id===me&&['owner','admin'].includes(m.role));
  const owner=club=>c.db.role==='admin'||club.ownerId===me;
  const known=()=>c.db.players.filter(p=>p.status==='approved');
  const roles={owner:'Eigenaar',admin:'Clubbeheerder',captain:'Aanvoerder',member:'Clublid'};
  function init(){c.db.play??={};const fresh=!state();if(fresh)c.db.play.clubs={items:[
    {id:701,name:'De Puinruimers',description:'Onze club, onze oche. Van gezellige clubavond tot online competitie: iedereen hoort erbij.',city:'Den Haag',visibility:'public',maxMembers:64,joinPolicy:'request',ownerId:9,members:[{id:9,role:'owner'},...Array.from({length:8},(_,i)=>({id:i+1,role:i===1?'captain':'member'}))],requests:[{id:70101,userId:10,status:'pending'}],code:'CLUB-PUIN',news:[{id:1,title:'Vrijdagavond weer aan de oche',text:'De Masters staat klaar. Check op tijd in en neem je clubmaatjes mee.',date:'2026-11-04T12:00:00Z',userId:9}],leagueIds:[501],tournamentIds:[1,2,3,4],roomIds:[]},
    {id:702,name:'Dartflow Social Club',description:'Jouw eigen vriendengroep, altijd een potje dichtbij. Spreek af, daag elkaar uit en bouw samen aan een mooie club.',city:'Online & overal',visibility:'private',maxMembers:16,joinPolicy:'request',ownerId:1,members:[{id:1,role:'owner'},{id:2,role:'admin'},{id:5,role:'member'}],requests:[],code:'CLUB-RUSH',news:[{id:2,title:'Welkom in onze vriendenclub',text:'Dit is jouw clubdemo. Je kunt leden beheren, nieuws plaatsen en een eigen clubkamer maken.',date:'2026-11-04T10:00:00Z',userId:1}],leagueIds:[],tournamentIds:[],roomIds:[]},
    {id:703,name:'Coastal Darts Collective',description:'Voor darters die samen beter willen worden. Oefenpotjes, doubles-training en een sportieve competitie.',city:'Scheveningen',visibility:'public',maxMembers:24,joinPolicy:'request',ownerId:11,members:[{id:11,role:'owner'},{id:12,role:'captain'},{id:13,role:'member'},{id:14,role:'member'},{id:15,role:'member'},{id:16,role:'member'}],requests:[],code:'CLUB-COAST',news:[],leagueIds:[],tournamentIds:[],roomIds:[]}
  ]};state().items.forEach(club=>{if(club.id===702&&club.name==='DartRush Social Club')club.name='Dartflow Social Club';club.requests??=[];club.news??=[];club.roomIds??=[];club.leagueIds??=[];club.tournamentIds??=[];});if(fresh&&c.db.play.community){makeRoom(state().items[0]);makeRoom(state().items[1]);}}
  const selected=()=>{const p=String(c.routeParam?.()||'');return state().items.find(x=>String(x.id)===p||x.code===p.toUpperCase());};
  const find=id=>state().items.find(x=>x.id===Number(id));
  const pending=club=>club.requests.filter(r=>r.status==='pending');
  const clubTag=club=>c.badge(club.visibility==='private'?'Privéclub':'Openbare club',club.visibility==='private'?'pending':'blue');
  const memberProfile=id=>`<span class="dr-inline">${c.avatar(id,'sm')}<span>${e(c.P(id).name)}</span></span>`;
  const roomList=()=>c.db.play.community?.rooms||[];
  function clubCard(club) {
    const joined = isMember(club);
    const requested = club.requests.some(r => r.userId === me && r.status === 'pending');
    const full = club.members.length >= club.maxMembers;
    const initials = club.name.split(' ').map(word => word[0]).slice(0, 2).join('');
    const membershipLabel = requested ? 'Aanvraag in behandeling' : full ? 'Club zit vol' : club.joinPolicy === 'open' ? 'Word lid' : 'Lidmaatschap aanvragen';
    return `<article class="panel dr-club-card">
      <header class="dr-club-card-head">
        <span class="dr-club-initial" aria-hidden="true">${e(initials)}</span>
        <div>
          <h2>${e(club.name)}</h2>
          <p class="dr-meta">${e(club.city)} · ${club.members.length}/${club.maxMembers} leden</p>
        </div>
      </header>
      <div class="dr-inline">${clubTag(club)}${joined ? c.badge('Jouw club','approved') : ''}</div>
      <p class="dr-meta">${e(club.description)}</p>
      <div class="dr-card-actions">
        ${B('Bekijk club','clubs-open','ghost small',`data-id="${club.id}"`)}
        ${joined
          ? B('Open clubomgeving','clubs-enter','gold small',`data-id="${club.id}"`)
          : B(membershipLabel,'clubs-join','ghost small',`data-id="${club.id}" ${requested || full ? 'disabled' : ''}`)}
      </div>
    </article>`;
  }
  function view(){init();const club=selected();if(club)return detail(club);const shown=state().items.filter(x=>filter==='mine'?isMember(x):x.visibility==='public'||isMember(x));return c.header('Verenigingen','Bekijk clubs, beheer je lidmaatschap of richt een eigen club op.',B(I('plus')+' Club oprichten','clubs-new','gold'))+`<div class="toolbar dr-list-toolbar"><div class="tabs">${[['discover','Ontdek clubs'],['mine','Mijn clubs']].map(([v,l])=>`<button type="button" class="tab ${filter===v?'active':''}" data-action="clubs-filter" data-value="${v}">${l}</button>`).join('')}</div><div class="dr-inline dr-list-search">${B('Clubcode invoeren','clubs-code','ghost small')}<div class="input-wrap">${I('search')}<input class="input" placeholder="Zoek een club…" aria-label="Zoek een club" id="clubs-search"></div></div></div><div class="dr-grid dr-grid-3 dr-card-grid">${shown.map(x=>`<div data-club-search="${e((x.name+' '+x.city).toLowerCase())}">${clubCard(x)}</div>`).join('')}</div><div class="notice" style="margin-top:22px">${I('info')}Clubleden, aanvragen en nieuws zijn lokale demogegevens. Je verstuurt geen echte uitnodigingen.</div>`;}
  function locked(club){return c.header(e(club.name),'Een privéclub voor genodigden.',B(I('left')+' Alle clubs','nav','ghost','data-to="clubs"'))+`<section class="panel dr-card"><div class="dr-inline">${I('shield')}${clubTag(club)}</div><h2>Alleen voor clubleden</h2><p class="subtle-label">Je hebt een uitnodigingscode nodig om lidmaatschap aan te vragen. De ledenlijst, clubkamers en activiteiten zijn privé.</p>${B('Uitnodigingscode invoeren','clubs-code','gold')}</section>`;}
  function detail(club){const viaCode=String(c.routeParam?.()||'').toUpperCase()===club.code;if(club.visibility==='private'&&!isMember(club)&&!manage(club)&&!viaCode)return locked(club);const joined=isMember(club),requested=club.requests.some(r=>r.userId===me&&r.status==='pending');const tabs=[['overview','Clubhuis'],['members','Leden'],['activities','Activiteiten'],['rooms','Clubkamers'],...(manage(club)?[['manage','Clubbeheer']]:[])];let active=tabs.some(x=>x[0]===tab)?tab:'overview';return c.header(e(club.name),`${e(club.city)} · ${club.members.length}/${club.maxMembers} leden`,`${B(I('left')+' Alle clubs','nav','ghost small','data-to="clubs"')}${joined?B('Open clubomgeving','clubs-enter','gold small',`data-id="${club.id}"`):''}${joined||manage(club)?B(I('users')+' Uitnodigen','clubs-invite',joined?'ghost small':'gold small',`data-id="${club.id}"`):B(requested?'Aanvraag in behandeling':'Lidmaatschap aanvragen','clubs-join','gold small',`data-id="${club.id}" ${requested?'disabled':''}`)}`)+`<section class="panel dr-club-header"><div class="dr-inline dr-wrap">${clubTag(club)}${joined?c.badge(roles[club.members.find(m=>m.id===me)?.role]||'Clublid','approved'):c.badge('Nog geen lid')}${manage(club)?c.badge('Beheer beschikbaar','pending'):''}</div><p>${e(club.description)}</p></section>${!joined&&!manage(club)?`<div class="notice" style="margin-top:18px">${I('info')}Word lid om het clubhuis, de leden en clubkamers te openen.</div>`:`<div class="tabs" style="margin-top:22px">${tabs.map(([v,l])=>`<button type="button" class="tab ${active===v?'active':''}" data-action="clubs-tab" data-value="${v}">${l}${v==='manage'&&pending(club).length?' ('+pending(club).length+')':''}</button>`).join('')}</div>${active==='overview'?overview(club):active==='members'?members(club):active==='activities'?activities(club):active==='rooms'?rooms(club):management(club)}`}`;}
  function overview(club){return `<div class="dr-grid dr-grid-2"><section class="panel dr-card"><div class="dr-inline" style="justify-content:space-between"><h2>Uit het clubhuis</h2>${manage(club)?B(I('plus')+' Nieuws plaatsen','clubs-news','ghost small',`data-id="${club.id}"`):''}</div>${club.news.length?club.news.slice().reverse().map(n=>`<article style="padding:17px 0;border-bottom:1px solid var(--line)"><h3>${e(n.title)}</h3><p class="subtle-label" style="white-space:pre-wrap">${e(n.text)}</p><small class="dr-meta">${e(c.P(n.userId).name)} · ${new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'short'}).format(new Date(n.date))}</small></article>`).join(''):'<p class="subtle-label">Nog geen clubnieuws. Plaats het eerste bericht.</p>'}</section><aside class="panel dr-card"><h2>De club leeft.</h2><div class="dr-mini-stats"><div><b>${club.members.length}</b><small>Leden</small></div><div><b>${club.roomIds.length}</b><small>Clubkamers</small></div></div><p class="subtle-label">Spreek samen af in een clubkamer, doe mee aan een competitie of start een toernooi.</p><div class="dr-inline dr-wrap">${B('Naar de clubkamers','clubs-show-rooms','gold small')}${B('Bekijk activiteiten','clubs-show-activities','ghost small')}</div>${isMember(club)?`<div style="margin-top:25px;border-top:1px solid var(--line);padding-top:15px">${B('Club verlaten','clubs-leave','ghost small',`data-id="${club.id}"`)}</div>`:''}</aside></div>`;}
  function members(club){return `<section class="panel full-table"><table class="table"><thead><tr><th>Clublid</th><th>Rol</th><th>Gemiddelde</th><th></th></tr></thead><tbody>${club.members.map(m=>`<tr><td>${memberProfile(m.id)}${m.id===me?' <small class="subtle-label">Jij</small>':''}</td><td>${c.badge(roles[m.role]||'Clublid',m.role==='owner'?'pending':'')}</td><td>${Number(c.P(m.id).avg||0).toFixed(1)}</td><td><div class="dr-inline">${m.id!==me?B('Uitdagen','clubs-challenge','gold small',`data-id="${m.id}" data-club="${club.id}"`):''}${owner(club)&&m.role!=='owner'?B('Rol wijzigen','clubs-role','ghost small',`data-id="${m.id}" data-club="${club.id}"`):''}${manage(club)&&m.role!=='owner'&&m.id!==me?B('Verwijderen','clubs-remove','ghost small',`data-id="${m.id}" data-club="${club.id}"`):''}</div></td></tr>`).join('')}</tbody></table></section>`;}
  function activities(club){const leagues=(c.db.play.leagues||[]).filter(x=>club.leagueIds.includes(x.id)),tournaments=c.db.tournaments.filter(x=>club.tournamentIds.includes(x.id));return `<div class="dr-grid dr-grid-2"><section class="panel dr-card"><div class="dr-inline" style="justify-content:space-between"><h2>Clubcompetities</h2>${manage(club)?B('Koppelen','clubs-link-activities','ghost small',`data-id="${club.id}"`):''}</div>${leagues.map(l=>`<article class="dr-fixture"><div><strong>${e(l.name)}</strong><small>${e(l.division)} · ${l.players.length} spelers</small></div>${B('Open competitie','clubs-league','gold small',`data-id="${l.id}"`)}</article>`).join('')||'<p class="subtle-label">Nog geen competitie gekoppeld.</p>'}${B('Alle competities','clubs-events','ghost small',`data-club="${club.id}" data-value="leagues"`)}</section><section class="panel dr-card"><h2>Clubtoernooien</h2>${tournaments.map(t=>`<article class="dr-fixture"><div><strong>${e(t.name)}</strong><small>${e(t.format)} · ${t.players} spelers</small></div>${B('Open toernooi','clubs-tournament','gold small',`data-id="${t.id}"`)}</article>`).join('')||'<p class="subtle-label">Nog geen toernooi gekoppeld.</p>'}${B('Alle toernooien','clubs-events','ghost small',`data-club="${club.id}" data-value="hall"`)}</section></div>`;}
  function rooms(club){const list=roomList().filter(r=>club.roomIds.includes(r.id));return `<section class="panel dr-card"><div class="dr-inline dr-wrap" style="justify-content:space-between"><div><h2>De ontmoeting begint hier.</h2><p class="subtle-label">Praat bij, daag een clublid uit of wacht samen op je volgende partij.</p></div>${manage(club)?B(I('plus')+' Clubkamer maken','clubs-new-room','gold small',`data-id="${club.id}"`):''}</div><div class="dr-grid dr-grid-2">${list.map(r=>`<article class="panel dr-card"><div class="dr-inline" style="justify-content:space-between"><h3>${e(r.name)}</h3>${c.badge(r.type==='private'?'Privé':'Clubkamer','pending')}</div><p class="subtle-label">${e(r.description||'De vaste plek voor jouw clubgenoten.')}</p><p class="dr-meta">${r.members.length}/${r.maxMembers} leden · Alleen jouw club</p>${B('Open clubkamer '+I('right'),'nav','gold small',`data-to="community/${r.id}"`)}</article>`).join('')||'<p class="subtle-label">Er is nog geen clubkamer. Maak er als clubbeheerder één aan.</p>'}</div></section>`;}
  function management(club){return `<div class="dr-grid dr-grid-2"><section class="panel dr-card"><div class="dr-inline dr-wrap" style="justify-content:space-between"><h2>Lidmaatschapsaanvragen</h2>${B('Simuleer aanvraag','clubs-demo-request','ghost small',`data-id="${club.id}"`)}</div>${pending(club).map(r=>`<article class="dr-fixture"><div>${memberProfile(r.userId)}<small>Wil lid worden van de club</small></div><div class="dr-inline">${B('Goedkeuren','clubs-approve','green small',`data-id="${r.id}" data-club="${club.id}"`)}${B('Afwijzen','clubs-reject','ghost small',`data-id="${r.id}" data-club="${club.id}"`)}</div></article>`).join('')||'<p class="subtle-label">Alle aanvragen zijn bijgewerkt.</p>'}<p class="dr-meta">${pending(club).length} openstaand · ${club.maxMembers-club.members.length} plaatsen beschikbaar</p></section><section class="panel dr-card"><h2>Clubinstellingen</h2><form data-form="clubs-settings"><input type="hidden" name="id" value="${club.id}"><label class="field">Clubnaam<input class="input" name="name" required maxlength="60" value="${e(club.name)}"></label><label class="field">Omschrijving<input class="input" name="description" maxlength="300" value="${e(club.description)}"></label><div class="field-row"><label class="field">Plaats<input class="input" name="city" maxlength="60" required value="${e(club.city)}"></label><label class="field">Maximum leden<input class="input" name="maxMembers" type="number" min="2" max="128" required value="${club.maxMembers}"></label></div><div class="field-row"><label class="field">Zichtbaarheid<select name="visibility"><option value="public" ${club.visibility==='public'?'selected':''}>Openbaar</option><option value="private" ${club.visibility==='private'?'selected':''}>Privé</option></select></label><label class="field">Lid worden<select name="joinPolicy"><option value="request" ${club.joinPolicy==='request'?'selected':''}>Na goedkeuring</option><option value="open" ${club.joinPolicy==='open'?'selected':''}>Direct toetreden</option></select></label></div><div class="inline-error" id="clubs-form-error"></div><button class="btn gold">Clubinstellingen opslaan</button></form></section></div>`;}
  function newClub(){c.showModal('Richt jouw club op.','Een eigen clubhuis voor je vrienden, team of vereniging.',`<form data-form="clubs-new"><label class="field">Clubnaam<input class="input" name="name" required maxlength="60" placeholder="Bijv. Vrijdagavond Royals"></label><label class="field">Omschrijving<input class="input" name="description" maxlength="300" placeholder="Wat maakt jullie club bijzonder?"></label><div class="field-row"><label class="field">Plaats<input class="input" name="city" required maxlength="60" value="Online & overal"></label><label class="field">Maximum leden<input class="input" name="maxMembers" type="number" min="2" max="128" value="24" required></label></div><div class="field-row"><label class="field">Zichtbaarheid<select name="visibility"><option value="public">Openbaar</option><option value="private">Privé</option></select></label><label class="field">Lid worden<select name="joinPolicy"><option value="request">Na goedkeuring</option><option value="open">Direct toetreden</option></select></label></div><div class="notice">${I('info')}Je bent eigenaar van de nieuwe democlub. Er wordt direct een privéclubkamer aangemaakt.</div><div class="inline-error" id="clubs-form-error"></div><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold">Club oprichten</button></div></form>`);}
  function enterCode(){c.showModal('Jouw uitnodiging voor de club.','Voer de clubcode in. Probeer bijvoorbeeld CLUB-RUSH.',`<form data-form="clubs-code"><label class="field">Clubcode<input class="input" name="code" required maxlength="30" placeholder="CLUB-XXXX" autocomplete="off"></label><div class="inline-error" id="clubs-form-error"></div><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold">Club openen</button></div></form>`);}
  function requestJoin(club,viaCode=false){if(!club||isMember(club))return;if(club.visibility==='private'&&!viaCode&&!manage(club)){enterCode();return;}if(club.members.length>=club.maxMembers){c.toast('Deze club heeft het maximum aantal leden bereikt.');return;}if(club.joinPolicy==='open'){club.members.push({id:me,role:'member'});syncRooms(club);playerMail(c,'club-decision',`club:${club.id}:join:${me}:${Date.now()}`,club.id,me,{status:'Welkom bij de club',actionUrl:mailUrl(c,'clubs/'+club.id)});c.save();c.render();c.toast('Je bent lid geworden van de club.');return;}if(club.requests.some(r=>r.userId===me&&r.status==='pending')){c.toast('Je aanvraag wordt al beoordeeld.');return;}const request={id:Date.now(),userId:me,status:'pending'};club.requests.push(request);clubTeamMail(c,'club-request',`club:${club.id}:request:${request.id}`,club,{actorName:c.P(me).name,actionUrl:mailUrl(c,'clubs/'+club.id)});c.save();c.render();c.toast('Je lidmaatschapsaanvraag staat klaar voor de clubbeheerder.');}
  function syncRooms(club){for(const r of roomList().filter(x=>club.roomIds.includes(x.id))){r.members=r.members.filter(m=>club.members.some(cm=>cm.id===m.id));club.members.forEach(m=>{if(!r.members.some(rm=>rm.id===m.id))r.members.push({id:m.id,role:m.role==='owner'?'host':m.role==='admin'?'moderator':'member',mutedUntil:0});});r.ownerId=club.ownerId;r.members.forEach(rm=>{const cm=club.members.find(x=>x.id===rm.id);rm.role=cm?.role==='owner'?'host':cm?.role==='admin'?'moderator':'member';});r.maxMembers=Math.max(club.maxMembers,r.members.length);r.invitedIds=(r.invitedIds||[]).filter(id=>club.members.some(m=>m.id===id));}}
  function makeRoom(club,name){const opts={name:name||club.name+' · Clubhuis',description:'De privéclubkamer van '+club.name,type:'private',maxMembers:club.maxMembers,ownerId:club.ownerId,clubId:club.id,members:club.members.map(m=>({id:m.id,role:m.role==='owner'?'host':m.role==='admin'?'moderator':'member',mutedUntil:0})),code:'ROOM-'+Math.random().toString(36).slice(2,7).toUpperCase()};let result=c.createCommunityRoom?.(opts),id=typeof result==='object'?result?.id:result;if(!id){c.db.play.community??={rooms:[]};const r={...opts,id:Date.now()+Math.floor(Math.random()*100),messages:[],bans:[],slowMode:0,challenges:[],invitedIds:[],archived:false,lastSentBy:{},joined:true,createdAt:new Date().toISOString()};c.db.play.community.rooms.push(r);id=r.id;}if(!club.roomIds.includes(id))club.roomIds.push(id);return id;}
  function formError(message){const el=document.getElementById('clubs-form-error');if(el)el.textContent=message;else c.toast(message);}
  async function copyInvite(club){const url=`${c.baseUrl||location.origin}/#clubs/${club.code}`;try{await navigator.clipboard.writeText(url);c.toast('Clubuitnodiging gekopieerd.');}catch{c.showModal('Deel jouw club.','Deze uitnodiging werkt met de lokale demogegevens.',`<label class="field">Uitnodigingslink<input class="input" readonly value="${e(url)}"></label><label class="field">Clubcode<input class="input" readonly value="${club.code}"></label>${B('Sluiten','close-modal','gold')}`);}}
  function handleAction(a,b){if(!a.startsWith('clubs-'))return false;init();const id=Number(b.dataset.id),club=find(b.dataset.club)||selected()||find(id);switch(a){
    case 'clubs-filter':filter=b.dataset.value;c.render();break;
    case 'clubs-open':tab='overview';c.go('clubs/'+id);break;
    case 'clubs-enter':{const target=find(id);if(!target||!isMember(target)){c.toast('Je moet eerst lid zijn van deze club om de clubomgeving te openen.');break;}c.db.play.activeClubId=target.id;c.save();c.go(c.db.role==='admin'?'dashboard':'home');c.toast('Je bent nu in de clubomgeving van '+target.name+'.');break;}
    case 'clubs-tab':tab=b.dataset.value;c.render();break;
    case 'clubs-new':newClub();break;
    case 'clubs-code':enterCode();break;
    case 'clubs-join':requestJoin(club,String(c.routeParam?.()||'').toUpperCase()===club?.code);break;
    case 'clubs-invite':if(club&&(isMember(club)||manage(club)))copyInvite(club);break;
    case 'clubs-show-rooms':tab='rooms';c.render();break;
    case 'clubs-show-activities':tab='activities';c.render();break;
    case 'clubs-league':case 'clubs-tournament':case 'clubs-events':{
      const league=a==='clubs-league'||a==='clubs-events'&&b.dataset.value==='leagues';
      const item=a==='clubs-events'?club:(league?c.db.play.leagues:c.db.tournaments)?.find(event=>Number(event.id)===id);
      if(!item)break;
      const target=a==='clubs-events'?club:find(item.clubId);
      if((a==='clubs-events'||item.clubId!=null)&&(!target||!isMember(target))){
        c.toast('Word eerst lid om de activiteiten van deze vereniging te openen.');break;
      }
      c.db.play.activeClubId=target?.id??null;
      if(a!=='clubs-events')c.db.play[league?'selectedLeague':'selectedHall']=id;
      c.save();c.go(league?'leagues':'hall');break;
    }
    case 'clubs-challenge':if(club&&isMember(club))c.createGame({opponentId:id,type:'practice',setup:'remote',startScore:501,bestOf:5,clubId:club.id});break;
    case 'clubs-demo-request':{if(!club||!manage(club))break;const p=known().find(p=>!club.members.some(m=>m.id===p.id)&&!club.requests.some(r=>r.userId===p.id&&r.status==='pending'));if(!p){c.toast('Alle voorbeeldspelers zijn al lid of aangemeld.');break;}const request={id:Date.now(),userId:p.id,status:'pending'};club.requests.push(request);clubTeamMail(c,'club-request',`club:${club.id}:request:${request.id}`,club,{actorName:p.name,actionUrl:mailUrl(c,'clubs/'+club.id)});c.save();c.render();c.toast('Demo: '+c.P(p.id).name+' vraagt lidmaatschap aan.');break;}
    case 'clubs-approve':case 'clubs-reject':{if(!club||!manage(club))break;const r=club.requests.find(r=>r.id===id);if(!r||r.status!=='pending')break;if(a==='clubs-approve'&&club.members.length>=club.maxMembers){c.toast('De club zit vol. Verhoog eerst de ledenlimiet.');break;}r.status=a==='clubs-approve'?'approved':'rejected';if(r.status==='approved'&&!club.members.some(m=>m.id===r.userId))club.members.push({id:r.userId,role:'member'});syncRooms(club);playerMail(c,'club-decision',`club:${club.id}:request:${r.id}:${r.status}`,club.id,r.userId,{status:r.status==='approved'?'Goedgekeurd':'Afgewezen',actionUrl:mailUrl(c,'clubs/'+club.id)});c.save();c.render();c.toast(r.status==='approved'?'Nieuw clublid goedgekeurd.':'Lidmaatschapsaanvraag afgewezen.');break;}
    case 'clubs-role':{if(!club||!owner(club))break;const m=club.members.find(m=>m.id===id);if(!m||m.role==='owner')break;c.showModal('Een rol in de club.',e(c.P(id).name)+' · '+e(club.name),`<form data-form="clubs-role"><input name="clubId" type="hidden" value="${club.id}"><input name="userId" type="hidden" value="${id}"><label class="field">Clubrol<select name="role">${[['member','Clublid'],['captain','Aanvoerder'],['admin','Clubbeheerder']].map(([v,l])=>`<option value="${v}" ${m.role===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="subtle-label">Clubbeheerders mogen leden en kamers beheren. Aanvoerders zijn zichtbaar als aanspreekpunt.</p><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold">Rol opslaan</button></div></form>`);break;}
    case 'clubs-remove':{if(!club||!manage(club))break;const m=club.members.find(m=>m.id===id);if(!m||m.role==='owner'||id===me)break;c.showModal('Clublid verwijderen?',`${e(c.P(id).name)} verliest toegang tot de club en gekoppelde clubkamers.`,`<div class="modal-actions">${B('Annuleren','close-modal','ghost')}${B('Verwijderen','clubs-confirm-remove','danger',`data-id="${id}" data-club="${club.id}"`)}</div>`);break;}
    case 'clubs-confirm-remove':if(club&&manage(club)&&id!==club.ownerId&&id!==me){club.members=club.members.filter(m=>m.id!==id);syncRooms(club);c.save();c.closeModal();c.render();c.toast('Het clublid is verwijderd.');}break;
    case 'clubs-leave':if(club&&isMember(club)){if(club.ownerId===me){const next=club.members.find(m=>m.id!==me);if(!next){c.toast('Je bent het enige lid en de eigenaar. Voeg eerst een opvolger toe.');break;}c.showModal('Draag de club over.',`Bij vertrek wordt ${e(c.P(next.id).name)} eigenaar van ${e(club.name)}.`,`<div class="modal-actions">${B('Blijven','close-modal','ghost')}${B('Overdragen & verlaten','clubs-confirm-leave','danger',`data-id="${club.id}"`)}</div>`);}else c.showModal('Club verlaten?',`Je verliest toegang tot ${e(club.name)} en de clubkamers.`,`<div class="modal-actions">${B('Blijven','close-modal','ghost')}${B('Club verlaten','clubs-confirm-leave','danger',`data-id="${club.id}"`)}</div>`);}break;
    case 'clubs-confirm-leave':if(club&&isMember(club)){if(club.ownerId===me){const next=club.members.find(m=>m.id!==me);if(!next)break;club.ownerId=next.id;next.role='owner';}club.members=club.members.filter(m=>m.id!==me);if(c.db.play.activeClubId===club.id)c.db.play.activeClubId=null;syncRooms(club);c.save();c.closeModal();tab='overview';c.go('clubs');c.toast('Je hebt de club verlaten.');}break;
    case 'clubs-news':if(club&&manage(club))c.showModal('Nieuws uit jouw club.',e(club.name),`<form data-form="clubs-news"><input name="id" type="hidden" value="${club.id}"><label class="field">Titel<input class="input" name="title" maxlength="80" required></label><label class="field">Bericht<textarea class="input" name="text" rows="5" maxlength="1500" required style="width:100%;resize:vertical"></textarea></label><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold">Nieuws plaatsen</button></div></form>`);break;
    case 'clubs-new-room':if(club&&manage(club))c.showModal('Een eigen clubkamer.',e(club.name),`<form data-form="clubs-room"><input name="id" type="hidden" value="${club.id}"><label class="field">Kamernaam<input class="input" name="name" maxlength="60" required value="${e(club.name)} · Clubhuis"></label><div class="notice">${I('shield')}Alle huidige clubleden krijgen toegang. De kamer blijft privé voor de club.</div><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold">Clubkamer maken</button></div></form>`);break;
    case 'clubs-link-activities':if(club&&manage(club))c.showModal('Activiteiten aan jouw club koppelen.',e(club.name),`<form data-form="clubs-activities"><input name="id" type="hidden" value="${club.id}"><label class="field">Competitie<select name="league"><option value="">Geen toevoegen</option>${(c.db.play.leagues||[]).map(l=>`<option value="${l.id}">${e(l.name)}</option>`).join('')}</select></label><label class="field">Toernooi<select name="tournament"><option value="">Geen toevoegen</option>${c.db.tournaments.map(t=>`<option value="${t.id}">${e(t.name)}</option>`).join('')}</select></label><div class="modal-actions">${B('Annuleren','close-modal','ghost')}<button class="btn gold">Activiteiten koppelen</button></div></form>`);break;
  }return true;}
  function handleForm(form,f){const type=form.dataset.form;if(!type?.startsWith('clubs-'))return false;init();if(type==='clubs-new'||type==='clubs-settings'){const name=f.name?.trim(),city=f.city?.trim(),max=Number(f.maxMembers);if(!name||!city){formError('Vul een clubnaam en plaats in.');return true;}if(!Number.isInteger(max)||max<2||max>128){formError('Kies een ledenlimiet tussen 2 en 128.');return true;}const values={name,city,maxMembers:max,description:f.description?.trim()||'',visibility:f.visibility==='private'?'private':'public',joinPolicy:f.joinPolicy==='open'?'open':'request'};if(type==='clubs-new'){const club={id:Date.now(),...values,ownerId:me,members:[{id:me,role:'owner'}],requests:[],code:'CLUB-'+Math.random().toString(36).slice(2,7).toUpperCase(),news:[],leagueIds:[],tournamentIds:[],roomIds:[]};state().items.push(club);makeRoom(club);c.save();c.closeModal();tab='overview';c.go('clubs/'+club.id);c.toast('Je club en privéclubkamer staan klaar.');}else{const club=find(f.id);if(!club||!manage(club))return true;if(max<club.members.length){formError('De limiet kan niet lager zijn dan het huidige aantal leden.');return true;}Object.assign(club,values);syncRooms(club);c.save();c.render();c.toast('De clubinstellingen zijn opgeslagen.');}}
    if(type==='clubs-code'){const code=f.code?.trim().toUpperCase(),club=state().items.find(x=>x.code===code);if(!club){formError('Deze clubcode is niet bekend in de demo.');return true;}c.closeModal();tab='overview';c.go('clubs/'+code);if(!isMember(club))requestJoin(club,true);}
    if(type==='clubs-role'){const club=find(f.clubId),m=club?.members.find(m=>m.id===Number(f.userId));if(!club||!owner(club)||!m||m.role==='owner'||!['admin','captain','member'].includes(f.role))return true;const previousRole=m.role;m.role=f.role;for(const r of roomList().filter(r=>club.roomIds.includes(r.id))){const rm=r.members.find(x=>x.id===m.id);if(rm)rm.role=m.role==='admin'?'moderator':'member';}if(previousRole!==m.role)playerMail(c,'club-role',`club:${club.id}:role:${m.id}:${Date.now()}`,club.id,m.id,{role:roles[m.role]||m.role,actionUrl:mailUrl(c,'clubs/'+club.id)});c.save();c.closeModal();c.render();c.toast('De clubrol is bijgewerkt.');}
    if(type==='clubs-news'){const club=find(f.id);if(!club||!manage(club)||!f.title?.trim()||!f.text?.trim())return true;club.news.push({id:Date.now(),title:f.title.trim(),text:f.text.trim(),date:new Date().toISOString(),userId:me});c.save();c.closeModal();c.render();c.toast('Het clubnieuws is geplaatst in de demo.');}
    if(type==='clubs-room'){const club=find(f.id);if(!club||!manage(club)||!f.name?.trim())return true;makeRoom(club,f.name.trim());c.save();c.closeModal();tab='rooms';c.render();c.toast('De privéclubkamer is aangemaakt.');}
    if(type==='clubs-activities'){const club=find(f.id);if(!club||!manage(club))return true;if(f.league&&!club.leagueIds.includes(Number(f.league)))club.leagueIds.push(Number(f.league));if(f.tournament&&!club.tournamentIds.includes(Number(f.tournament)))club.tournamentIds.push(Number(f.tournament));c.save();c.closeModal();c.render();c.toast('De activiteiten zijn gekoppeld aan jouw club.');}
    return true;}
  if(typeof document!=='undefined')document.addEventListener('input',event=>{if(event.target.id==='clubs-search'){const query=event.target.value.toLowerCase();document.querySelectorAll('[data-club-search]').forEach(el=>{el.hidden=!el.dataset.clubSearch.includes(query);});}});
  return{init,view,handleAction,handleForm};
}
